namespace StarlightSyndicateDemo;
public sealed class FreightJob {public string Origin{get;set;}="";public string Destination{get;set;}="";public string Item{get;set;}="";public int Quantity{get;set;}public decimal Reward{get;set;}public decimal Collateral{get;set;}public bool Complete{get;set;}}
public sealed partial class Ship {public FreightJob? FreightContract{get;set;}}
public sealed partial class DemoWorld
{
 public bool AcceptFreightContract(){if(!Docked||!Player.Specialist||!ShipBatch21.ById.TryGetValue(Player.CombatHull,out var p)||p.Role!="Hauling"||Player.FreightContract!=null)return false;
  string key=CargoAllocation().Holds.FirstOrDefault(h=>h.Key!="fleetHangarCapacity"&&h.Key!="specialFuelBayCapacity")?.Key??"";string item=key switch{"specialMineralHoldCapacity"=>"mineral24","specialPlanetaryCommoditiesHoldCapacity"=>"planetary24","specialAmmoHoldCapacity"=>"ammo","specialColonyResourcesHoldCapacity"=>"infrastructure24","generalMiningHoldCapacity"=>"ore","specialGasHoldCapacity"=>"gas","specialIceHoldCapacity"=>"ice",_=>"planetary24"};
  int qty=(int)Math.Min(Math.Min(100000,Math.Floor(CargoRoom(item)*.65f/ItemVolume(item))),Math.Floor((double)(Balance*.8m/ItemCatalog.Get(item).Price)));if(qty<1)return false;string destination=Current.Links.First();Player.FreightContract=new(){Origin=SystemId,Destination=destination,Item=item,Quantity=qty,Collateral=qty*ItemCatalog.Get(item).Price,Reward=Math.Round(250+qty*(decimal)ItemVolume(item)*.035m,2)};WalletChange(-Player.FreightContract.Collateral,"Freight collateral / "+Player.HullName);ChangeStack(item,false,(decimal)(qty));Say("Freight loaded: "+qty+" "+ItemName(item)+" to "+Systems.First(s=>s.Id==destination).Name+". Deliver from this fitted ship.");return true;
 }
 public bool DeliverFreightContract(){var j=Player.FreightContract;if(!Docked||j==null||j.Complete||SystemId!=j.Destination||ItemCount(j.Item,false)<j.Quantity)return false;ChangeStack(j.Item,false,-(decimal)(j.Quantity));j.Complete=true;WalletChange(j.Reward+j.Collateral,"Freight delivery and collateral refund / "+Player.HullName);Say("Freight delivered / "+j.Reward+" CR. Each purchased hull carries one introductory freight contract.");return true;}
 public bool RefineSpecialistOre(){if(!Docked||!Player.Specialist||ItemCount("ore",false)<100)return false;int batches=(int)Math.Floor(ItemCount("ore",false)/100);ChangeStack("ore",false,-(decimal)(100*batches));Hangar["mineral24"]=Hangar.GetValueOrDefault("mineral24")+20*batches;Say("Refined "+100*batches+" ore into "+20*batches+" alloy; output in station hangar.");return true;}
}
